--// ZENITH CLAN🍁 intro by NOX
--// Plays the video, then shows ZENITH CLAN🍁 at the end (+ optional Toji voice)
--// Video is embedded in this script (~3.5 MB), so no links needed.

local TOJI_VOICE_ID = "" -- paste a Roblox sound id here (numbers only) for the Toji voice line, or leave empty
local TOJI_VOICE_FILE = "" -- OR the name of an audio file in your executor workspace folder, e.g. "toji.mp3"

local Players = game:GetService("Players")
local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")
local lp = Players.LocalPlayer

local DATA = [==[]==]

local function pureDecode(s)
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local map = {}
	for i = 1, #chars do map[chars:byte(i)] = i - 1 end
	local out, n = {}, 0
	local len = #s
	for i = 1, len, 4 do
		local a, b, c, d = s:byte(i, i + 3)
		local A, B = map[a] or 0, map[b] or 0
		local C, D = map[c], map[d]
		local v = A * 262144 + B * 4096 + (C or 0) * 64 + (D or 0)
		local b1 = math.floor(v / 65536)
		local b2 = math.floor(v / 256) % 256
		local b3 = v % 256
		n += 1
		if C == nil then out[n] = string.char(b1)
		elseif D == nil then out[n] = string.char(b1, b2)
		else out[n] = string.char(b1, b2, b3) end
		if n % 40000 == 0 then task.wait() end
	end
	return table.concat(out)
end

local function decode(s)
	local f = (crypt and crypt.base64decode) or (crypt and crypt.base64 and crypt.base64.decode)
		or base64decode or base64_decode or (base64 and base64.decode)
	if f then
		local ok, res = pcall(f, s)
		if ok and res and #res > 1000 then return res end
	end
	return pureDecode(s)
end

-- GUI parent
local parent
pcall(function() parent = gethui and gethui() end)
if not parent then
	local ok = pcall(function() parent = game:GetService("CoreGui") end)
	if not ok or not parent then parent = lp:WaitForChild("PlayerGui") end
end
pcall(function()
	local old = parent:FindFirstChild("ZenithClanIntro")
	if old then old:Destroy() end
end)

local gui = Instance.new("ScreenGui")
gui.Name = "ZenithClanIntro"
gui.IgnoreGuiInset = true
gui.ResetOnSpawn = false
gui.DisplayOrder = 999999
gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
gui.Parent = parent

local bg = Instance.new("Frame")
bg.Size = UDim2.fromScale(1, 1)
bg.BackgroundColor3 = Color3.new(0, 0, 0)
bg.BorderSizePixel = 0
bg.Parent = gui

local loading = Instance.new("TextLabel")
loading.Size = UDim2.fromScale(1, 1)
loading.BackgroundTransparency = 1
loading.Text = "Loading..."
loading.TextColor3 = Color3.fromRGB(200, 200, 200)
loading.Font = Enum.Font.GothamBold
loading.TextScaled = true
loading.Size = UDim2.fromScale(0.3, 0.06)
loading.Position = UDim2.fromScale(0.35, 0.47)
loading.Parent = bg

-- prepare video file
local asset
local ok, err = pcall(function()
	local bytes = decode(DATA)
	writefile("zenith_clan_intro.mp4", bytes)
	asset = getcustomasset("zenith_clan_intro.mp4")
end)
DATA = nil
if not ok or not asset then
	loading.Text = "Executor can't play video"
	warn("[ZENITH] failed:", err)
	task.wait(3)
	gui:Destroy()
	return
end
loading:Destroy()

local video = Instance.new("VideoFrame")
video.Size = UDim2.fromScale(1, 1)
video.BackgroundTransparency = 1
video.Video = asset
video.Looped = false
video.Volume = 1
video.Parent = bg

-- end screen
local endText = Instance.new("TextLabel")
endText.AnchorPoint = Vector2.new(0.5, 0.5)
endText.Position = UDim2.fromScale(0.5, 0.5)
endText.Size = UDim2.fromScale(0.9, 0.25)
endText.BackgroundTransparency = 1
endText.Text = "ZENITH CLAN🍁"
endText.TextScaled = true
endText.Font = Enum.Font.GothamBlack
endText.TextColor3 = Color3.fromRGB(255, 255, 255)
endText.TextTransparency = 1
endText.Parent = bg

local stroke = Instance.new("UIStroke")
stroke.Color = Color3.fromRGB(255, 120, 0)
stroke.Thickness = 3
stroke.Transparency = 1
stroke.Parent = endText

local finished = false
local function finish()
	if finished then return end
	finished = true
	pcall(function() video:Pause() end)
	TweenService:Create(video, TweenInfo.new(0.6), {Volume = 0}):Play()
	task.wait(0.6)
	video.Visible = false

	-- Toji voice line
	local snd = Instance.new("Sound")
	snd.Volume = 3
	snd.Parent = gui
	local played = false
	if TOJI_VOICE_FILE ~= "" then
		pcall(function()
			snd.SoundId = getcustomasset(TOJI_VOICE_FILE)
			played = true
		end)
	end
	if not played and TOJI_VOICE_ID ~= "" then
		snd.SoundId = "rbxassetid://" .. TOJI_VOICE_ID
		played = true
	end
	if played then snd:Play() end

	TweenService:Create(endText, TweenInfo.new(0.5, Enum.EasingStyle.Quad), {TextTransparency = 0}):Play()
	TweenService:Create(stroke, TweenInfo.new(0.5), {Transparency = 0}):Play()
	endText.Size = UDim2.fromScale(0.6, 0.15)
	TweenService:Create(endText, TweenInfo.new(1.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Size = UDim2.fromScale(0.9, 0.25)}):Play()

	task.wait(4.5)
	TweenService:Create(endText, TweenInfo.new(0.8), {TextTransparency = 1}):Play()
	TweenService:Create(stroke, TweenInfo.new(0.8), {Transparency = 1}):Play()
	TweenService:Create(bg, TweenInfo.new(0.8), {BackgroundTransparency = 1}):Play()
	task.wait(0.9)
	gui:Destroy()
end

video.Ended:Connect(finish)
video.Playing = true
video:Play()

-- safety: if Ended never fires, end after the video length
task.delay(11.5, finish)
